@keyframes markerAttention {
  0%, 100% { transform: scale(1); }
  50% { transform: scale(1.14); }
}

/* ---------- HUD ---------- */
#hud {
  position: absolute;
  inset: 0;
  z-index: 6;
  pointer-events: none;
}

.hud-top {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  padding: 20px 24px;
  gap: 20px;
}

.brand {
  display: flex;
  align-items: center;
  gap: 12px;
  text-shadow: 0 2px 12px rgba(0, 0, 0, 0.8);
}

.brand-mark {
  position: relative;
  width: 34px;
  height: 34px;
  border: 1px solid rgba(95, 233, 255, 0.55);
  border-radius: 50%;
  display: grid;
  place-items: center;
  box-shadow: 0 0 20px rgba(95, 233, 255, 0.14), inset 0 0 14px rgba(95, 233, 255, 0.1);
}

.brand-mark::before,
.brand-mark::after {
  content: '';
  position: absolute;
  background: var(--cyan);
  box-shadow: 0 0 8px var(--cyan);
}
.brand-mark::before { width: 12px; height: 1px; }
.brand-mark::after { width: 1px; height: 12px; }
.brand-mark i {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: var(--cyan);
  box-shadow: 0 0 10px var(--cyan);
}

.brand strong {
  display: block;
  font-family: var(--display);
  font-size: 19px;
  font-weight: 700;
  letter-spacing: 0.18em;
  line-height: 1;
  color: #e7fbff;
}

.brand span {
  display: block;
  margin-top: 4px;
  font-family: var(--mono);
  font-size: 8.5px;
  letter-spacing: 0.22em;
  color: var(--muted);
}

.hud-actions {
  display: flex;
  align-items: center;
  gap: 8px;
  pointer-events: auto;
}

.timer {
  display: flex;
  align-items: baseline;
  gap: 7px;
  height: 38px;
  padding: 0 13px;
  border: 1px solid var(--line);
  border-radius: 4px;
  background: rgba(4, 10, 14, 0.62);
  backdrop-filter: blur(12px);
}

.timer span {
  font-family: var(--mono);
  font-size: 9px;
  color: var(--muted);
  letter-spacing: 0.16em;
}

.timer strong {
  font-family: var(--mono);
  font-size: 14px;
  font-weight: 500;
  letter-spacing: 0.08em;
  color: #dffaff;
  font-variant-numeric: tabular-nums;
}

.icon-btn {
  width: 38px;
  height: 38px;
  display: grid;
  place-items: center;
  border: 1px solid var(--line);
  border-radius: 4px;
  background: rgba(4, 10, 14, 0.62);
  color: #bfeaf6;
  backdrop-filter: blur(12px);
  transition: border-color 0.18s ease, background 0.18s ease, color 0.18s ease, transform 0.18s ease;
}

.icon-btn svg {
  width: 17px;
  height: 17px;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.6;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.icon-btn:hover {
  border-color: var(--line-strong);
  background: rgba(15, 37, 48, 0.8);
  color: var(--cyan);
}

.icon-btn:active {
  transform: translateY(1px);
}

#sound-btn .sound-off {
  display: none;
}

#sound-btn.muted .sound-wave {
  display: none;
}

#sound-btn.muted .sound-off {
  display: inline;
}

#sound-btn.muted {
  color: var(--muted);
}

.glass {
  border: 1px solid var(--line);
  background: linear-gradient(158deg, rgba(10, 21, 29, 0.84), rgba(4, 10, 15, 0.62));
  backdrop-filter: blur(16px);
  box-shadow: 0 18px 60px rgba(0, 0, 0, 0.22), inset 0 1px 0 rgba(255, 255, 255, 0.03);
}

.objectives {
  width: 284px;
  margin: 0 0 0 24px;
  border-radius: 6px;
  padding: 14px 15px 14px;
  pointer-events: none;
}

.objectives::before {
  content: '';
  position: absolute;
  left: -1px;
  top: 16px;
  bottom: 16px;
  width: 1px;
  background: linear-gradient(180deg, transparent, var(--cyan), transparent);
  opacity: 0.55;
}

.objectives {
  position: relative;
}

.objectives-head {
  display: flex;
  justify-content: space-between;
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: 0.18em;
  color: var(--muted);
}

.objectives-head span:last-child {
  color: var(--cyan-dim);
}

.objective-bar {
  height: 2px;
  margin: 9px 0 12px;
  background: rgba(95, 233, 255, 0.1);
  overflow: hidden;
}

.objective-bar i {
  display: block;
  width: 0;
  height: 100%;
  background: linear-gradient(90deg, var(--cyan-deep), var(--cyan));
  box-shadow: 0 0 10px rgba(95, 233, 255, 0.55);
  transition: width 0.6s cubic-bezier(0.2, 0.8, 0.2, 1);
}

#objective-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 8px;
}

#objective-list li {
  display: flex;
  gap: 9px;
  align-items: flex-start;
  opacity: 0.46;
  transition: opacity 0.3s ease;
}

#objective-list li.active {
  opacity: 1;
}

#objective-list li.done {
  opacity: 0.44;
}

.obj-dot {
  flex: none;
  width: 11px;
  height: 11px;
  margin-top: 4px;
  border: 1px solid rgba(95, 233, 255, 0.4);
  border-radius: 50%;
  position: relative;
}

#objective-list li.active .obj-dot {
  border-color: var(--cyan);
  box-shadow: 0 0 12px rgba(95, 233, 255, 0.45);
}

#objective-list li.active .obj-dot::after {
  content: '';
  position: absolute;
  inset: 3px;
  border-radius: 50%;
  background: var(--cyan);
  animation: smallPulse 1.8s ease-in-out infinite;
}

#objective-list li.done .obj-dot {
  border-color: rgba(93, 255, 176, 0.55);
  background: rgba(93, 255, 176, 0.1);
}

#objective-list li.done .obj-dot::after {
  content: '';
  position: absolute;
  left: 2px;
  top: 2px;
  width: 4px;
  height: 2px;
  border-left: 1px solid var(--green);
  border-bottom: 1px solid var(--green);
  transform: rotate(-45deg);
}

@keyframes smallPulse {
  0%, 100% { transform: scale(0.7); opacity: 0.55; }
  50% { transform: scale(1); opacity: 1; }
}

.obj-copy strong {
  display: block;
  font-size: 13.5px;
  font-weight: 600;
  letter-spacing: 0.035em;
  color: #d5f1fa;
  line-height: 1.2;
}

.obj-copy em {
  display: block;
  font-style: normal;
  font-family: var(--mono);
  font-size: 8.5px;
  letter-spacing: 0.08em;
  color: var(--muted);
  margin-top: 2px;
}

#objective-list li.done .obj-copy strong {
  text-decoration: line-through;
  text-decoration-color: rgba(93, 255, 176, 0.5);
}

.inventory {
  position: absolute;
  left: 24px;
  bottom: 24px;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 9px 10px;
  border-radius: 6px;
  pointer-events: auto;
}

.inventory-label {
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.2em;
  color: var(--muted);
  writing-mode: vertical-rl;
  transform: rotate(180deg);
  margin-right: 3px;
}

.slot {
  position: relative;
  width: 50px;
  height: 50px;
  border: 1px solid rgba(95, 233, 255, 0.14);
  border-radius: 3px;
  background: rgba(3, 9, 13, 0.55);
  display: grid;
  place-items: center;
  color: var(--muted-2);
  overflow: hidden;
  transition: border-color 0.25s ease, background 0.25s ease, color 0.25s ease;
}

.slot::before {
  content: '';
  position: absolute;
  inset: 5px;
  border: 1px dashed rgba(95, 233, 255, 0.07);
  border-radius: 2px;
}

.slot.filled {
  color: var(--cyan);
  border-color: rgba(95, 233, 255, 0.38);
  background: radial-gradient(circle at 50% 35%, rgba(95, 233, 255, 0.16), rgba(3, 9, 13, 0.6) 72%);
  box-shadow: inset 0 0 20px rgba(95, 233, 255, 0.08);
}

.slot.filled::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, transparent 30%, rgba(95, 233, 255, 0.08) 50%, transparent 70%);
}

.slot .slot-icon {
  font-family: var(--mono);
  font-size: 17px;
  text-shadow: 0 0 12px rgba(95, 233, 255, 0.7);
  z-index: 1;
}

.slot .slot-name {

.toast.error .toast-kicker { color: var(--red); }

/* ---------- assistant panel ---------- */
#assistant {
  position: relative;
  z-index: 8;
  display: flex;
  flex-direction: column;
  min-height: 0;
  border-left: 1px solid var(--line);
  background:
    radial-gradient(ellipse at 50% 0%, rgba(30, 96, 118, 0.18), transparent 48%),
    linear-gradient(180deg, #08121a 0%, #050b10 54%, #03070b 100%);
  box-shadow: -24px 0 80px rgba(0, 0, 0, 0.4);
}

#assistant::before {
  content: '';
  position: absolute;
  inset: 0;
  pointer-events: none;
  opacity: 0.4;
  background-image:
    linear-gradient(rgba(95, 233, 255, 0.028) 1px, transparent 1px),
    linear-gradient(90deg, rgba(95, 233, 255, 0.028) 1px, transparent 1px);
  background-size: 34px 34px;
  mask-image: linear-gradient(180deg, black, transparent 65%);
}

.assistant-head {
  position: relative;
  display: flex;
  align-items: center;
  gap: 13px;
  padding: 20px 18px 14px;
  border-bottom: 1px solid rgba(95, 233, 255, 0.08);
}

.pip-avatar {
  position: relative;
  flex: none;
  width: 46px;
  height: 46px;
  border-radius: 50%;
  background: radial-gradient(circle at 34% 28%, #b8fbff 0%, #37c7e0 32%, #0b5264 66%, #04161e 100%);
  box-shadow: 0 0 28px rgba(95, 233, 255, 0.28), inset 0 0 16px rgba(255, 255, 255, 0.28);
}

.pip-core {
  position: absolute;
  inset: 16px;
  border-radius: 50%;
  background: radial-gradient(circle at 40% 35%, #e7feff, #6eefff 60%, #1e849d);
  box-shadow: 0 0 18px rgba(95, 233, 255, 0.95);
  animation: pipBreath 3.6s ease-in-out infinite;
}

.pip-ring {
  position: absolute;
  inset: -5px;
  border: 1px solid rgba(95, 233, 255, 0.32);
  border-radius: 50%;
  border-top-color: transparent;
  border-bottom-color: rgba(95, 233, 255, 0.06);
  animation: spin 7s linear infinite;
}

.pip-ring.r2 {
  inset: -10px;
  border-color: rgba(95, 233, 255, 0.12);
  border-left-color: transparent;
  animation-duration: 13s;
  animation-direction: reverse;
}

@keyframes spin { to { transform: rotate(360deg); } }
@keyframes pipBreath {
  0%, 100% { transform: scale(1); opacity: 0.9; }
  50% { transform: scale(1.08); opacity: 1; }
}

.assistant-id {
  min-width: 0;
  flex: 1;
}

.assistant-name-row {
  display: flex;
  align-items: center;
  gap: 9px;
}

.assistant-id h2 {
  margin: 0;
  font-size: 21px;
  font-weight: 700;
  letter-spacing: 0.14em;
  line-height: 1;
  color: #e7fbff;
}

.live-tag {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 2px 5px;
  border: 1px solid rgba(93, 255, 176, 0.3);
  border-radius: 2px;
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: 0.16em;
  color: var(--green);
}

.live-tag i {
  width: 3px;
  height: 3px;
  border-radius: 50%;
  background: var(--green);
  box-shadow: 0 0 6px var(--green);
  animation: smallPulse 1.6s infinite;
}

.assistant-id p {
  margin: 5px 0 0;
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.13em;
  text-transform: uppercase;
  color: var(--muted);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.assistant-toggle svg {
  transition: transform 0.25s ease;
}

#assistant.collapsed .assistant-toggle svg {
  transform: rotate(180deg);
}

.assistant-status {
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 8px 19px;
  border-bottom: 1px solid rgba(95, 233, 255, 0.06);
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--muted);
}

.waveform {
  display: flex;
  align-items: center;
  gap: 2px;
  height: 10px;
}

.waveform i {
  display: block;
  width: 1.5px;
  height: 4px;
  background: var(--cyan);
  box-shadow: 0 0 5px var(--cyan);
  animation: wave 1.4s ease-in-out infinite;
}

.waveform i:nth-child(2) { animation-delay: 0.1s; }
.waveform i:nth-child(3) { animation-delay: 0.2s; }
.waveform i:nth-child(4) { animation-delay: 0.3s; }
.waveform i:nth-child(5) { animation-delay: 0.4s; }
.waveform i:nth-child(6) { animation-delay: 0.5s; }
.waveform i:nth-child(7) { animation-delay: 0.6s; }

@keyframes wave {
  0%, 100% { height: 3px; opacity: 0.5; }
  50% { height: 10px; opacity: 1; }
}

.assistant-signal {
  margin-left: auto;
  color: rgba(93, 255, 176, 0.7);
}

.chat {
  position: relative;
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  overscroll-behavior: contain;
  padding: 16px 18px 8px;
  display: flex;
  flex-direction: column;
  gap: 13px;
  scrollbar-width: thin;
  scrollbar-color: rgba(95, 233, 255, 0.18) transparent;
}

.chat::-webkit-scrollbar {
  width: 5px;
}
.chat::-webkit-scrollbar-thumb {
  background: rgba(95, 233, 255, 0.16);
  border-radius: 9px;
}

.message {
  display: flex;
  gap: 9px;
  max-width: 95%;
  opacity: 0;
  transform: translateY(7px);
  transition: opacity 0.32s ease, transform 0.32s ease;
}

.message.visible {
  opacity: 1;
  transform: translateY(0);
}

.message.player {
  align-self: flex-end;
  flex-direction: row-reverse;
}

.message-avatar {
  flex: none;
  width: 24px;
  height: 24px;
  margin-top: 3px;
  border: 1px solid rgba(95, 233, 255, 0.34);
  border-radius: 50%;
  display: grid;
  place-items: center;
  background: radial-gradient(circle at 35% 30%, rgba(95, 233, 255, 0.5), rgba(8, 20, 27, 0.9));
  font-family: var(--mono);
  font-size: 8px;
  color: #dffbff;
  box-shadow: 0 0 12px rgba(95, 233, 255, 0.18);
}

.message-body {
  min-width: 0;
}

.bubble {
  position: relative;
  padding: 9px 12px 8px;
  border: 1px solid rgba(95, 233, 255, 0.13);
  border-radius: 3px 13px 13px 13px;
  background: linear-gradient(160deg, rgba(16, 39, 51, 0.78), rgba(7, 17, 24, 0.82));
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.18);
}

.bubble p {
  margin: 0;
  font-family: var(--display);
  font-size: 13.5px;
  font-weight: 500;
  line-height: 1.48;
  color: #c8e9f4;
  letter-spacing: 0.01em;
}

.message-time {
  display: block;
  margin-top: 4px;
  font-family: var(--mono);
  font-size: 7.5px;
  letter-spacing: 0.1em;
  color: rgba(120, 149, 165, 0.56);
}

.message.player .bubble {
  border-color: rgba(255, 180, 94, 0.2);
  border-radius: 13px 3px 13px 13px;
  background: linear-gradient(160deg, rgba(48, 35, 17, 0.82), rgba(21, 17, 11, 0.86));
}

.message.player .bubble p {
  color: #ffe6c2;
}

.message.player .message-time {
  text-align: right;
}

.message.tone-alert .bubble {
  border-color: rgba(255, 180, 94, 0.32);
}

.message.tone-win .bubble {
  border-color: rgba(93, 255, 176, 0.35);
}

.typing-message {
  opacity: 1;
  transform: none;
}

.bubble.typing {
  display: flex;
  gap: 4px;
  align-items: center;
  min-width: 48px;
  padding: 13px 13px;
}

.bubble.typing span {
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: var(--cyan);
  opacity: 0.4;
  animation: typing 1.2s ease-in-out infinite;
}

.bubble.typing span:nth-child(2) { animation-delay: 0.14s; }
.bubble.typing span:nth-child(3) { animation-delay: 0.28s; }

@keyframes typing {
  0%, 100% { transform: translateY(0); opacity: 0.3; }
  50% { transform: translateY(-3px); opacity: 1; }
}

.quick-row {
  position: relative;
  display: flex;
  gap: 6px;
  padding: 10px 18px 8px;
}

.chip {
  flex: 1;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  height: 31px;
  padding: 0 10px;
  border: 1px solid rgba(95, 233, 255, 0.18);
  border-radius: 3px;
  background: rgba(7, 16, 22, 0.6);
  color: #a9d5e3;
  font-family: var(--mono);
  font-size: 8.5px;
  letter-spacing: 0.13em;
  text-transform: uppercase;
  transition: border-color 0.18s ease, color 0.18s ease, background 0.18s ease;
}

.chip:hover {
  border-color: rgba(95, 233, 255, 0.42);
  color: var(--cyan);
