:root {
  --bg: #04080c;
  --panel: rgba(8, 15, 21, 0.86);
  --panel-soft: rgba(11, 22, 30, 0.64);
  --line: rgba(108, 205, 235, 0.16);
  --line-strong: rgba(108, 205, 235, 0.34);
  --cyan: #5fe9ff;
  --cyan-deep: #1cb3d1;
  --cyan-dim: rgba(95, 233, 255, 0.58);
  --amber: #ffb45e;
  --amber-deep: #d77b2d;
  --red: #ff5d6e;
  --green: #5dffb0;
  --text: #d8edf6;
  --muted: #7895a5;
  --muted-2: #4d6775;
  --mono: 'JetBrains Mono', ui-monospace, SFMono-Regular, Consolas, monospace;
  --display: 'Rajdhani', ui-sans-serif, system-ui, sans-serif;
  color-scheme: dark;
}

* {
  box-sizing: border-box;
}

html,
body {
  height: 100%;
  margin: 0;
}

body {
  overflow: hidden;
  background: var(--bg);
  color: var(--text);
  font-family: var(--display);
  font-size: 16px;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

button,
input {
  font: inherit;
  color: inherit;
}

button {
  cursor: pointer;
}

button:focus-visible,
input:focus-visible {
  outline: 2px solid var(--cyan);
  outline-offset: 3px;
}

::selection {
  background: rgba(95, 233, 255, 0.28);
}

#app {
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1fr) 396px;
  height: 100vh;
  height: 100dvh;
  overflow: hidden;
}

body:not(.playing) #app {
  display: none;
}

#viewport {
  position: relative;
  min-width: 0;
.slot .slot-name {
  position: absolute;
  bottom: 4px;
  left: 0;
  right: 0;
  text-align: center;
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: 0.08em;
  color: var(--cyan-dim);
  text-transform: uppercase;
  z-index: 1;
}

.slot .slot-empty {
  font-family: var(--mono);
  font-size: 14px;
  color: rgba(120, 149, 165, 0.22);
}

.look-hint {
  position: absolute;
  left: 50%;
  bottom: 28px;
  transform: translateX(-50%);
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 7px 12px;
  border: 1px solid rgba(95, 233, 255, 0.1);
  border-radius: 99px;
  background: rgba(3, 9, 13, 0.44);
  color: var(--muted);
  font-family: var(--mono);
  font-size: 8.5px;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  backdrop-filter: blur(8px);
  transition: opacity 0.5s ease;
}

.look-hint svg {
  width: 16px;
  height: 16px;
  fill: none;
  stroke: var(--cyan-dim);
  stroke-width: 1.4;
  stroke-linecap: round;
}

.look-pad {
  position: absolute;
  right: 20px;
  bottom: 24px;
  display: none;
  gap: 6px;
  pointer-events: auto;
}

.toast {
  position: absolute;
  right: 24px;
  top: 78px;
  transform: translateY(-14px);
  min-width: 240px;
  max-width: min(360px, calc(100% - 48px));
  padding: 12px 16px 13px;
  border: 1px solid var(--line-strong);
  border-radius: 5px;
  background: rgba(4, 13, 18, 0.93);
  box-shadow: 0 22px 60px rgba(0, 0, 0, 0.55), inset 0 1px 0 rgba(255, 255, 255, 0.04);
  backdrop-filter: blur(14px);
  opacity: 0;
  visibility: hidden;
  transition: opacity 0.3s ease, transform 0.3s ease, visibility 0.3s;
  pointer-events: none;
  z-index: 12;
}

.toast.show {
  opacity: 1;
  visibility: visible;
  transform: translateY(0);
}

.toast-kicker {
  display: block;
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.22em;
  color: var(--cyan-dim);
  margin-bottom: 4px;
}

.toast strong {
  display: block;
  font-size: 16px;
  font-weight: 600;
  letter-spacing: 0.03em;
  color: #e5fbff;
}

.toast p {
  margin: 3px 0 0;
  font-size: 12.5px;
  line-height: 1.4;
  color: var(--muted);
}

.toast.success {
  border-color: rgba(93, 255, 176, 0.4);
}
.toast.success .toast-kicker { color: var(--green); }
.toast.warn {
  border-color: rgba(255, 180, 94, 0.4);
}
.toast.warn .toast-kicker { color: var(--amber); }
.toast.error {
  border-color: rgba(255, 93, 110, 0.45);
}
.toast.error .toast-kicker { color: var(--red); }
  letter-spacing: 0.04em;
  color: var(--muted-2);
  text-align: center;
}

.keypad-card.shake {
  animation: shake 0.4s ease;
}

/* ---------- ending ---------- */
.ending-screen {
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px;
  background:
    radial-gradient(ellipse at 50% 42%, rgba(42, 196, 222, 0.16), transparent 55%),
    radial-gradient(ellipse at 50% 110%, rgba(255, 170, 80, 0.12), transparent 50%),
    rgba(2, 6, 10, 0.95);
  backdrop-filter: blur(18px);
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
  transition: opacity 0.9s ease, visibility 0.9s;
}

.ending-screen::before {
  content: '';
  position: absolute;
  inset: 0;
  background:
    repeating-linear-gradient(90deg, transparent 0 118px, rgba(95, 233, 255, 0.03) 118px 119px),
    repeating-linear-gradient(0deg, transparent 0 118px, rgba(95, 233, 255, 0.03) 118px 119px);
  mask-image: radial-gradient(ellipse at center, black, transparent 72%);
  pointer-events: none;
}

.ending-screen.show {
  opacity: 1;
  visibility: visible;
  pointer-events: auto;
}

.ending-card {
  position: relative;
  z-index: 1;
  width: min(620px, 92vw);
  padding: 38px 42px 32px;
  border: 1px solid rgba(95, 233, 255, 0.26);
  border-radius: 8px;
