}

.intro-pip-orb i {
  position: absolute;
  inset: 21px;
  border-radius: 50%;
  background: radial-gradient(circle at 40% 35%, #f2ffff, #6cefff 62%, #1e849d);
  box-shadow: 0 0 18px rgba(95, 233, 255, 0.9);
}

.intro-quote {
  margin: 0;
  font-size: 19px;
  font-weight: 500;
  line-height: 1.42;
  color: #d5f3fb;
  letter-spacing: 0.015em;
}

.intro-pip-meta {
  display: flex;
  justify-content: space-between;
  margin-top: 22px;
  padding-top: 14px;
  border-top: 1px solid rgba(95, 233, 255, 0.1);
  font-family: var(--mono);
  font-size: 7.5px;
  letter-spacing: 0.18em;
  color: var(--muted);
}

.intro-pip-meta span:first-child {
  color: var(--cyan-dim);
}

.intro-specs {
  display: flex;
  flex-direction: column;
  gap: 8px;
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.16em;
  color: rgba(120, 149, 165, 0.72);
}

.intro-specs span {
  display: flex;
  align-items: center;
  gap: 8px;
}

.intro-specs i {
  width: 3px;
  height: 3px;
  border-radius: 50%;
  background: var(--cyan);
  box-shadow: 0 0 6px var(--cyan);
}

.intro-footer {
  position: absolute;
  left: clamp(24px, 5vw, 72px);
  right: clamp(24px, 5vw, 72px);
  bottom: 24px;
  z-index: 1;
  display: flex;
  justify-content: space-between;
  font-family: var(--mono);
  font-size: 7.5px;
  letter-spacing: 0.16em;
  color: rgba(120, 149, 165, 0.5);
}

/* ---------- modals ---------- */
.modal {
  position: fixed;
  inset: 0;
  z-index: 50;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px;
  background: rgba(1, 4, 7, 0.76);
  backdrop-filter: blur(10px);
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
  transition: opacity 0.3s ease, visibility 0.3s;
}

.modal.show {
  opacity: 1;
  visibility: visible;
  pointer-events: auto;
}

.modal-card {
  position: relative;
  width: min(940px, 96vw);
  max-height: 92vh;
  overflow: auto;
  border: 1px solid rgba(95, 233, 255, 0.24);
  border-radius: 8px;
  background:
    radial-gradient(ellipse at 12% 0%, rgba(27, 122, 145, 0.18), transparent 42%),
    linear-gradient(160deg, #091520 0%, #050d13 62%, #04090d 100%);
  box-shadow: 0 40px 140px rgba(0, 0, 0, 0.7), inset 0 1px 0 rgba(255, 255, 255, 0.05);
  transform: translateY(14px) scale(0.985);
  transition: transform 0.35s cubic-bezier(0.2, 0.8, 0.2, 1);
  scrollbar-width: thin;
  scrollbar-color: rgba(95, 233, 255, 0.18) transparent;
}

.modal.show .modal-card {
  transform: translateY(0) scale(1);
}

.modal-card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 26px;
  right: 26px;
  height: 1px;
  background: linear-gradient(90deg, transparent, var(--cyan), transparent);
  opacity: 0.55;
}

.modal-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
  padding: 22px 24px 16px;
  border-bottom: 1px solid rgba(95, 233, 255, 0.1);
}

.modal-head .eyebrow {
  margin-bottom: 7px;
}

.modal-head h2 {
  margin: 0;
  font-size: 30px;
  font-weight: 600;
  letter-spacing: 0.03em;
  color: #ecfcff;
}

.modal-close {
  flex: none;
}

.constellation-body {
  display: grid;
  grid-template-columns: minmax(0, 1.18fr) minmax(250px, 0.82fr);
  gap: 22px;
  padding: 22px 24px;
}

.starmap-wrap {
  min-width: 0;
}

.starmap {
  position: relative;
  aspect-ratio: 1.18;
  border: 1px solid rgba(95, 233, 255, 0.18);
  border-radius: 5px;
  overflow: hidden;
  background:
    radial-gradient(ellipse at 50% 45%, rgba(24, 99, 122, 0.16), transparent 62%),
    radial-gradient(ellipse at 26% 28%, rgba(100, 40, 130, 0.14), transparent 45%),
    #02070b;
  box-shadow: inset 0 0 80px rgba(0, 0, 0, 0.7);
}

.starmap::after {
  content: '';
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: repeating-linear-gradient(0deg, rgba(95, 233, 255, 0.035) 0 1px, transparent 1px 4px);
  opacity: 0.6;
}

.starmap.shake {
  animation: shake 0.4s ease;
}

@keyframes shake {
  0%, 100% { transform: translateX(0); }
  20% { transform: translateX(-7px); }
  40% { transform: translateX(6px); }
  60% { transform: translateX(-4px); }
  80% { transform: translateX(3px); }
}

.starmap-grid {
  position: absolute;
  inset: 0;
  background-image:
    linear-gradient(rgba(95, 233, 255, 0.045) 1px, transparent 1px),
    linear-gradient(90deg, rgba(95, 233, 255, 0.045) 1px, transparent 1px);
  background-size: 10% 10%;
  mask-image: radial-gradient(ellipse at center, black, transparent 80%);
}

.starmap-core {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: rgba(95, 233, 255, 0.35);
  box-shadow: 0 0 10px rgba(95, 233, 255, 0.5);
  transform: translate(-50%, -50%);
}

#star-connector {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  z-index: 1;
  pointer-events: none;
  overflow: visible;
}

#star-line {
  fill: none;
  stroke: rgba(95, 233, 255, 0.8);
  stroke-width: 1.4;
  stroke-linejoin: round;
  stroke-linecap: round;
  filter: drop-shadow(0 0 4px rgba(95, 233, 255, 0.85));
  opacity: 0;
  transition: opacity 0.25s ease;
}

#star-line.visible {
  opacity: 1;
}

.star {
  position: absolute;
  z-index: 2;
  width: 32px;
  height: 32px;
  padding: 0;
  border: 0;
  background: transparent;
  transform: translate(-50%, -50%);
  display: grid;
  place-items: center;
  color: var(--cyan);
}

.star-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: #bff8ff;
  box-shadow: 0 0 10px rgba(160, 240, 255, 0.9), 0 0 30px rgba(95, 233, 255, 0.4);
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.star[data-kind="red"] .star-dot {
  width: 11px;
  height: 11px;
  background: #ff9a7a;
  box-shadow: 0 0 14px rgba(255, 128, 90, 0.95), 0 0 40px rgba(255, 90, 50, 0.45);
}

.star[data-kind="eye"] .star-dot {
  background: #ffe27a;
  box-shadow: 0 0 14px rgba(255, 226, 122, 0.95), 0 0 40px rgba(255, 190, 60, 0.4);
}

.star[data-kind="decoy"] .star-dot {
  width: 5px;
  height: 5px;
  background: rgba(180, 220, 235, 0.55);
  box-shadow: 0 0 8px rgba(180, 220, 235, 0.4);
}

.star .star-name {
  position: absolute;
  top: 28px;
  left: 50%;
  transform: translateX(-50%);
  padding: 3px 6px;
  border: 1px solid rgba(95, 233, 255, 0.2);
  border-radius: 2px;
  background: rgba(2, 8, 11, 0.9);
  font-family: var(--mono);
  font-size: 7.5px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  white-space: nowrap;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.18s ease;
}

.star:hover .star-name,
.star:focus-visible .star-name {
  opacity: 1;
}

.star:hover .star-dot,
.star.selected .star-dot {
  transform: scale(1.6);
  box-shadow: 0 0 20px rgba(160, 240, 255, 1), 0 0 50px rgba(95, 233, 255, 0.6);
}

.star.selected {
  color: var(--green);
}

.star.selected .star-dot {
  background: var(--green);
  box-shadow: 0 0 18px rgba(93, 255, 176, 0.9), 0 0 44px rgba(93, 255, 176, 0.4);
}

.star.wrong .star-dot {
  background: var(--red);
  box-shadow: 0 0 18px rgba(255, 93, 110, 0.9);
}

.starmap-legend {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-top: 10px;
  font-family: var(--mono);
  font-size: 7.5px;
  letter-spacing: 0.13em;
  color: var(--muted);
}

.legend-dot {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  display: inline-block;
}
.legend-dot.red { background: #ff9a7a; box-shadow: 0 0 6px #ff9a7a; }
.legend-dot.cyan { background: #bff8ff; box-shadow: 0 0 6px #bff8ff; margin-left: 10px; }
.legend-dot.gold { background: #ffe27a; box-shadow: 0 0 6px #ffe27a; margin-left: 10px; }

.constellation-info {
  display: flex;
  flex-direction: column;
  gap: 13px;
}

.clue-label {
  margin: 0;
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.2em;
  color: var(--muted);
}

.clue-text {
  margin: 0;
  min-height: 64px;
  padding: 12px 13px;
  border-left: 1px solid rgba(95, 233, 255, 0.34);
  background: linear-gradient(90deg, rgba(95, 233, 255, 0.06), transparent);
  font-size: 15px;
  font-weight: 500;
  line-height: 1.45;
  color: #c6ebf6;
}

.sequence-pips {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 6px;
}

.pip-slot {
  padding: 8px 7px 7px;
  border: 1px solid rgba(95, 233, 255, 0.12);
  border-radius: 3px;
  background: rgba(3, 9, 13, 0.55);
  transition: border-color 0.25s ease, background 0.25s ease;
}

.pip-slot b {
  display: block;
  font-family: var(--mono);
  font-size: 7px;
  font-weight: 400;
  letter-spacing: 0.12em;
  color: var(--muted-2);
}

.pip-slot em {
  display: block;
  margin-top: 3px;
  font-family: var(--mono);
  font-size: 8px;
  font-style: normal;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--muted-2);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.pip-slot.filled {
  border-color: rgba(95, 233, 255, 0.42);
  background: rgba(17, 48, 61, 0.4);
}

.pip-slot.filled b {
  color: var(--cyan);
}

.pip-slot.filled em {
  color: #d4f8ff;
}

.status-line {
  padding: 7px 10px;
  border: 1px solid rgba(95, 233, 255, 0.12);
  border-radius: 3px;
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.18em;
  color: var(--amber);
  text-align: center;
  background: rgba(40, 27, 9, 0.28);
}

.status-line.ok {
  color: var(--green);
  border-color: rgba(93, 255, 176, 0.34);
  background: rgba(8, 34, 24, 0.3);
}

.status-line.bad {
  color: var(--red);
  border-color: rgba(255, 93, 110, 0.34);
  background: rgba(42, 8, 12, 0.3);
}

.code-reveal {
  display: none;
  padding: 13px 14px;
  border: 1px solid rgba(93, 255, 176, 0.4);
  border-radius: 4px;
  background: radial-gradient(ellipse at 50% 0%, rgba(93, 255, 176, 0.12), rgba(3, 12, 9, 0.5));
  text-align: center;
}

.code-reveal.visible {
  display: block;
  animation: revealCode 0.6s cubic-bezier(0.2, 0.8, 0.2, 1);
}

@keyframes revealCode {
  from { opacity: 0; transform: scale(0.94); }
  to { opacity: 1; transform: scale(1); }
}

.code-reveal span {
  display: block;
  font-family: var(--mono);
  font-size: 7.5px;
  letter-spacing: 0.2em;
  color: var(--green);
}

.code-reveal strong {
  display: block;
  margin: 4px 0 2px;
  font-family: var(--mono);
  font-size: 31px;
  font-weight: 500;
  letter-spacing: 0.3em;
  color: #ddfff1;
  text-shadow: 0 0 24px rgba(93, 255, 176, 0.5);
}

.code-reveal small {
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: 0.11em;
  color: rgba(93, 255, 176, 0.7);
}

.modal-note {
  margin: 0;
  font-family: var(--mono);
  font-size: 8px;
  line-height: 1.6;
  letter-spacing: 0.04em;
  color: var(--muted-2);
}

.modal-foot {
  display: flex;
  justify-content: space-between;
  padding: 11px 24px;
  border-top: 1px solid rgba(95, 233, 255, 0.1);
  font-family: var(--mono);
  font-size: 7.5px;
  letter-spacing: 0.15em;
  color: var(--muted-2);
}

.modal-foot b {
  color: var(--cyan-dim);
  font-weight: 400;
}

.keypad-card {
  width: min(400px, 96vw);
}

.keypad-screen {
  margin: 20px 24px 16px;
  padding: 15px;
  border: 1px solid rgba(95, 233, 255, 0.24);
  border-radius: 4px;
  background:
    repeating-linear-gradient(0deg, rgba(95, 233, 255, 0.035) 0 1px, transparent 1px 3px),
    radial-gradient(ellipse at 50% 0%, rgba(24, 120, 140, 0.16), rgba(2, 9, 13, 0.9));
  text-align: center;
  box-shadow: inset 0 0 36px rgba(0, 0, 0, 0.5);
}

.keypad-lock-label {
  display: block;
  font-family: var(--mono);
  font-size: 7.5px;
  letter-spacing: 0.2em;
  color: var(--muted);
}

#keypad-code {
  display: block;
  margin: 8px 0 6px;
  font-family: var(--mono);
  font-size: 38px;
  font-weight: 500;
  letter-spacing: 0.32em;
  color: var(--cyan);
  text-shadow: 0 0 22px rgba(95, 233, 255, 0.55);
}

.keypad-status {
  display: inline-block;
  padding: 2px 7px;
  border: 1px solid rgba(255, 180, 94, 0.28);
  border-radius: 2px;
  font-family: var(--mono);
  font-size: 7.5px;
  letter-spacing: 0.18em;
  color: var(--amber);
}

.keypad-status.ok {
  border-color: rgba(93, 255, 176, 0.34);
  color: var(--green);
}

.keypad-status.bad {
  border-color: rgba(255, 93, 110, 0.4);
  color: var(--red);
}

.keypad-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 7px;
  padding: 0 24px;
}

.keypad-key {
  height: 52px;
  border: 1px solid rgba(95, 233, 255, 0.16);
  border-radius: 3px;
  background: linear-gradient(160deg, rgba(16, 37, 48, 0.72), rgba(4, 11, 16, 0.8));
  font-family: var(--mono);
  font-size: 17px;
  font-weight: 500;
  color: #c9f1fb;
  transition: border-color 0.15s ease, background 0.15s ease, transform 0.1s ease;
}

.keypad-key:hover {
  border-color: rgba(95, 233, 255, 0.5);
  background: rgba(22, 62, 77, 0.7);
  color: var(--cyan);
}

.keypad-key:active {
  transform: scale(0.97);
}

.keypad-key.zero {
  grid-column: 1 / -1;
}

.keypad-actions {
  display: flex;
  gap: 7px;
  padding: 8px 24px 0;
}

.keypad-wide {
  flex: 1;
  height: 38px;
  border: 1px solid rgba(95, 233, 255, 0.16);
  border-radius: 3px;
  background: rgba(6, 16, 22, 0.7);
  font-family: var(--mono);
  font-size: 8.5px;
  letter-spacing: 0.18em;
  color: var(--muted);
  transition: border-color 0.15s ease, color 0.15s ease;
}

.keypad-wide:hover {
  border-color: rgba(95, 233, 255, 0.4);
  color: var(--cyan);
}

.keypad-wide.accent {
  border-color: rgba(95, 233, 255, 0.34);
  color: var(--cyan);
  background: rgba(18, 66, 82, 0.36);
}

.keypad-hint {
  margin: 14px 24px 20px;
  font-family: var(--mono);
  font-size: 8px;
  line-height: 1.6;
  letter-spacing: 0.04em;
  color: var(--muted-2);
  text-align: center;
}

.keypad-card.shake {
  animation: shake 0.4s ease;
}

/* ---------- ending ---------- */
.ending-screen {

  100% { opacity: 0; }
}

body.modal-open #hud,
body.modal-open .markers {
  filter: blur(1px);
}

