  }
  .starmap {
    aspect-ratio: 1.3;
  }
  .modal-head {
    padding: 16px 18px 12px;
  }
  .modal-head h2 {
    font-size: 24px;
  }
  .modal-foot {
    padding: 9px 18px;
  }
  .ending-card {
    padding: 28px 22px 24px;
  }
}

@media (max-width: 560px) {
  #app {
    grid-template-rows: minmax(0, 1fr) min(42vh, 360px);
  }
  .brand strong {
    font-size: 15px;
  }
  .brand span {
    font-size: 7px;
  }
  .brand-mark {
    width: 28px;
    height: 28px;
  }
  .timer {
    height: 34px;
