cat >> styles.css <<'EOF'

/* ---------- deck progression + co-pilot loadout ---------- */
body[data-deck="engineering"] {
  --cyan: #ffb45e;
  --cyan-deep: #d77b2d;
  --cyan-dim: rgba(255, 180, 94, 0.6);
  --line: rgba(255, 180, 94, 0.17);
  --line-strong: rgba(255, 180, 94, 0.36);
}

body[data-deck="bridge"] {
  --cyan: #b6a9ff;
  --cyan-deep: #7462d8;
  --cyan-dim: rgba(182, 169, 255, 0.62);
  --line: rgba(182, 169, 255, 0.18);
  --line-strong: rgba(182, 169, 255, 0.38);
}

.hud-left {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 9px;
  min-width: 0;
}

.deck-rail {
  display: flex;
  align-items: center;
  gap: 5px;
  pointer-events: none;
}

.deck-pill {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  min-width: 0;
  padding: 3px 7px;
  border: 1px solid rgba(120, 149, 165, 0.16);
  border-radius: 2px;
  background: rgba(3, 9, 13, 0.52);
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: 0.1em;
  color: rgba(120, 149, 165, 0.5);
  backdrop-filter: blur(8px);
  transition: border-color 0.3s ease, color 0.3s ease, background 0.3s ease;
}

.deck-pill i {
  width: 4px;
  height: 4px;
  flex: none;
  border-radius: 50%;
  background: currentColor;
}

.deck-pill b {
  font-weight: 500;
  white-space: nowrap;
}

.deck-pill span {
  font-size: 6.5px;
  letter-spacing: 0.13em;
  opacity: 0.78;
  white-space: nowrap;
}

.deck-pill.active {
  border-color: var(--line-strong);
  background: rgba(15, 37, 48, 0.7);
  color: var(--cyan);
  box-shadow: 0 0 16px rgba(95, 233, 255, 0.1);
}

.deck-pill.active i {
  box-shadow: 0 0 8px currentColor;
  animation: smallPulse 1.8s ease-in-out infinite;
}

.deck-pill.cleared {
  border-color: rgba(93, 255, 176, 0.28);
  color: rgba(93, 255, 176, 0.8);
}

.deck-pill.locked {
  opacity: 0.42;
}

.pip-loadout {
  flex: none;
  padding: 10px 18px 11px;
  border-bottom: 1px solid rgba(95, 233, 255, 0.07);
  background:
    linear-gradient(180deg, rgba(18, 49, 62, 0.2), transparent),
    rgba(3, 9, 13, 0.2);
}

.pip-loadout-head {
  display: flex;
  align-items: center;
  gap: 10px;
}

.pip-level {
  font-family: var(--mono);
  font-size: 7.5px;
  letter-spacing: 0.15em;
  color: var(--muted);
}

.pip-level b {
  color: var(--cyan);
  font-weight: 500;
}

.gem-readout {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  margin-left: auto;
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: 0.1em;
  color: #ffe1a3;
}

.gem-readout i {
  font-style: normal;
  font-size: 10px;
  color: var(--amber);
  text-shadow: 0 0 10px rgba(255, 180, 94, 0.7);
}

.gem-readout b {
  font-weight: 500;
  font-variant-numeric: tabular-nums;
}

.loadout-toggle {
  height: 21px;
  padding: 0 7px;
  border: 1px solid rgba(95, 233, 255, 0.16);
  border-radius: 2px;
  background: rgba(7, 16, 22, 0.55);
  font-family: var(--mono);
  font-size: 6.5px;
  letter-spacing: 0.15em;
  color: var(--muted);
  transition: border-color 0.18s ease, color 0.18s ease;
}

.loadout-toggle:hover {
  border-color: var(--line-strong);
  color: var(--cyan);
}

.pip-xp {
  height: 2px;
  margin: 7px 0 7px;
  overflow: hidden;
  background: rgba(95, 233, 255, 0.09);
}

.pip-xp i {
  display: block;
  width: 0;
  height: 100%;
  background: linear-gradient(90deg, var(--cyan-deep), var(--cyan));
  box-shadow: 0 0 10px rgba(95, 233, 255, 0.48);
  transition: width 0.5s cubic-bezier(0.2, 0.8, 0.2, 1);
}

.skill-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 4px;
  max-height: 108px;
  overflow-y: auto;
  scrollbar-width: thin;
  scrollbar-color: rgba(95, 233, 255, 0.16) transparent;
}

.pip-loadout.collapsed .skill-grid,
.pip-loadout.collapsed .pip-xp {
  display: none;
}

.skill {
  display: grid;
  grid-template-columns: 14px minmax(0, 1fr) auto;
  align-items: center;
  gap: 4px;
  min-height: 28px;
  padding: 4px 5px;
  border: 1px solid rgba(95, 233, 255, 0.11);
  border-radius: 2px;
  background: rgba(4, 12, 17, 0.55);
