  color: var(--muted);
  transition: border-color 0.18s ease, background 0.18s ease, color 0.18s ease;
}

.skill .skill-icon {
  display: grid;
  place-items: center;
  width: 14px;
  height: 14px;
  font-family: var(--mono);
  font-size: 10px;
  color: var(--cyan-dim);
}

.skill .skill-name {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-family: var(--mono);
  font-size: 6.5px;
  letter-spacing: 0.04em;
  color: #a9d5e3;
}

.skill .skill-cost {
  font-family: var(--mono);
  font-size: 6px;
  letter-spacing: 0.04em;
  color: rgba(255, 180, 94, 0.72);
  white-space: nowrap;
}

.skill.ready {
  border-color: var(--line-strong);
  background: rgba(17, 46, 58, 0.42);
}

.skill.ready:hover {
  border-color: var(--cyan);
  color: var(--cyan);
  background: rgba(25, 69, 86, 0.55);
  box-shadow: 0 0 14px rgba(95, 233, 255, 0.1);
}

.skill.locked {
  opacity: 0.35;
  filter: saturate(0.4);
}

.skill:disabled {
  cursor: default;
}

.skill.locked .skill-cost {
  color: var(--muted-2);
}

/* ---------- deck clear transition ---------- */
.deck-clear-screen {
  z-index: 45;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px;
  background:
    radial-gradient(ellipse at 50% 45%, rgba(42, 196, 222, 0.16), transparent 58%),
    radial-gradient(ellipse at 50% 110%, rgba(255, 170, 80, 0.12), transparent 52%),
    rgba(2, 6, 10, 0.92);
  backdrop-filter: blur(16px);
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
  transition: opacity 0.55s ease, visibility 0.55s;
}

.deck-clear-screen.show {
  opacity: 1;
  visibility: visible;
  pointer-events: auto;
}

.deck-clear-card {
  position: relative;
  width: min(660px, 92vw);
  padding: 38px 42px 32px;
  border: 1px solid var(--line-strong);
  border-radius: 8px;
  background:
    radial-gradient(ellipse at 50% 0%, rgba(42, 196, 222, 0.12), transparent 55%),
    linear-gradient(160deg, rgba(10, 27, 36, 0.94), rgba(3, 9, 13, 0.94));
  box-shadow: 0 40px 120px rgba(0, 0, 0, 0.65), inset 0 1px 0 rgba(255, 255, 255, 0.05);
  text-align: center;
}

.deck-clear-card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 30px;
  right: 30px;
  height: 1px;
  background: linear-gradient(90deg, transparent, var(--cyan), transparent);
}

.deck-clear-card .eyebrow {
  justify-content: center;
  color: var(--green);
}

.deck-clear-card .eyebrow span {
  background: var(--green);
  box-shadow: 0 0 8px var(--green);
}

.deck-clear-card h2 {
  margin: 4px 0 12px;
  font-size: clamp(2.4rem, 6vw, 4rem);
  font-weight: 700;
  line-height: 0.9;
  letter-spacing: 0.05em;
  color: #f0fdff;
}

.deck-clear-card h2 span {
  display: block;
  color: var(--cyan);
  text-shadow: 0 0 34px rgba(95, 233, 255, 0.35);
}

.deck-clear-lead {
  max-width: 440px;
  margin: 0 auto 22px;
  font-size: 14.5px;
  line-height: 1.5;
  color: #a9cbd8;
}

.deck-clear-rewards {
  display: grid;
  grid-template-columns: 1fr 1.35fr;
  gap: 8px;
  margin: 0 auto 16px;
  max-width: 480px;
}

.clear-reward {
  padding: 12px 10px;
  border: 1px solid rgba(255, 180, 94, 0.24);
  border-radius: 4px;
  background: rgba(40, 27, 9, 0.24);
}

.clear-reward.skill-reward {
  border-color: rgba(95, 233, 255, 0.24);
  background: rgba(8, 26, 34, 0.35);
}

.clear-reward-label {
  display: block;
  font-family: var(--mono);
  font-size: 6.5px;
  letter-spacing: 0.18em;
  color: var(--muted);
}

.clear-reward strong {
  display: block;
  margin-top: 5px;
  font-family: var(--mono);
  font-size: 17px;
  font-weight: 500;
  letter-spacing: 0.06em;
  color: #ffe1a3;
}

.clear-reward.skill-reward strong {
  color: var(--cyan);
}

.deck-clear-next {
  display: flex;
  flex-direction: column;
  gap: 4px;
  margin-bottom: 22px;
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: 0.18em;
  color: var(--muted);
}

.deck-clear-next b {
  font-size: 10px;
  font-weight: 500;
  letter-spacing: 0.16em;
  color: var(--green);
}

.deck-clear-card .start-btn {
  height: 50px;
  margin: 0 auto;
  font-size: 12px;
  letter-spacing: 0.24em;
}

/* ---------- reactor breaker grid ---------- */
.breaker-card {
  width: min(780px, 96vw);
}

.breaker-body {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(230px, 0.78fr);
  gap: 24px;
  padding: 22px 24px;
}

.breaker-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
  width: 100%;
  max-width: 390px;
  margin: auto;
  aspect-ratio: 1;
}

.breaker-cell {
  border: 1px solid rgba(255, 180, 94, 0.16);
  border-radius: 4px;
  background:
    repeating-linear-gradient(0deg, rgba(255, 180, 94, 0.02) 0 1px, transparent 1px 4px),
    rgba(5, 11, 15, 0.85);
  font-family: var(--mono);
  font-size: 12px;
  letter-spacing: 0.1em;
  color: rgba(120, 149, 165, 0.42);
  transition: border-color 0.15s ease, background 0.2s ease, color 0.2s ease, box-shadow 0.2s ease, transform 0.1s ease;
}

.breaker-cell:hover {
  border-color: rgba(255, 180, 94, 0.5);
  color: var(--amber);
}

.breaker-cell:active {
  transform: scale(0.97);
}

.breaker-cell.lit {
  border-color: rgba(255, 180, 94, 0.55);
  background:
    radial-gradient(circle at 50% 45%, rgba(255, 180, 94, 0.28), rgba(30, 17, 5, 0.72) 70%),
    rgba(5, 11, 15, 0.85);
  color: #ffe1a3;
  text-shadow: 0 0 12px rgba(255, 180, 94, 0.8);
  box-shadow: inset 0 0 24px rgba(255, 180, 94, 0.12), 0 0 16px rgba(255, 180, 94, 0.08);
}

.breaker-info {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.breaker-meter {
  height: 4px;
  overflow: hidden;
  border-radius: 99px;
  background: rgba(255, 180, 94, 0.12);
