async (page) => {
  const wait = (ms) => page.waitForTimeout(ms);
  const marker = async (id) => {
    await page.evaluate((mid) => {
      const el = document.querySelector(`.marker[data-id="${mid}"]`);
      if (!el) throw new Error('missing marker ' + mid);
      el.click();
    }, id);
    await wait(320);
  };
  const stars = async (ids) => {
    for (const id of ids) {
      await page.evaluate((sid) => {
        const el = document.querySelector(`.star[data-id="${sid}"]`);
        if (!el) throw new Error('missing star ' + sid);
        el.click();
      }, id);
      await wait(150);
    }
  };
  const digits = async (code) => {
    for (const d of code.split('')) {
      await page.evaluate((digit) => {
        const b = [...document.querySelectorAll('#keypad-grid .keypad-key')].find((x) => x.textContent.trim() === digit);
        if (!b) throw new Error('missing key ' + digit);
        b.click();
      }, d);
      await wait(130);
    }
    await wait(1300);
  };
  const closeModal = async (sel) => {
    await page.evaluate((s) => document.querySelector(s + ' .modal-close')?.click(), sel);
    await wait(280);
  };
  const state = async () => page.evaluate(() => ({
    deck: document.querySelector('#deck-label')?.textContent,
    gems: document.querySelector('#gem-count')?.textContent,
    skills: [...document.querySelectorAll('#skill-list .skill')].filter((b) => !b.classList.contains('locked')).map((b) => b.dataset.skill),
    objective: document.querySelector('#obj-progress')?.textContent,
    clear: document.querySelector('#deck-clear')?.classList.contains('show'),
    ending: document.querySelector('#ending')?.classList.contains('show'),
  }));

  const log = [];
  await page.goto('http://localhost:3002/');
  await wait(900);
  await page.click('#start-btn');
  await wait(900);
  log.push(['start', await state()]);

  // DECK 1
  await marker('drawer');
  await marker('fuse');
  await marker('relay');
  await marker('plaque');
  await marker('starchart');
  await wait(350);
  await stars(['red', 'castor', 'pollux', 'eye']);
  await wait(250);
  await closeModal('#constellation-modal');
  await marker('keypad');
  await digits('7394');
  await closeModal('#keypad-modal');
  log.push(['deck1-ready', await state()]);
  await marker('door');
  await wait(1100);
  log.push(['deck1-clear', await state()]);
  await page.click('#next-deck-btn');
  await wait(900);
  log.push(['deck2', await state()]);

  // DECK 2
  await marker('drawer');
  await marker('fuse');
  await marker('server');
  await wait(300);
  for (const i of [0, 4, 7]) {
    await page.evaluate((cell) => document.querySelector(`.breaker-cell[data-cell="${cell}"]`)?.click(), i);
    await wait(180);
  }
  await wait(1800);
  log.push(['deck2-ready', await state()]);
  await marker('door');
  await wait(1500);
  log.push(['deck2-clear', await state()]);
  await page.click('#next-deck-btn');
  await wait(900);
  log.push(['deck3', await state()]);

  // DECK 3
  await marker('window');
  await marker('starchart');
  await wait(350);
  await stars(['eye', 'castor', 'red', 'pollux']);
  await wait(250);
  await closeModal('#constellation-modal');
  await marker('keypad');
  await digits('4826');
  await closeModal('#keypad-modal');
  log.push(['deck3-ready', await state()]);
  await marker('door');
  await wait(2100);
  const ending = await page.evaluate(() => ({
    show: document.querySelector('#ending')?.classList.contains('show'),
    rank: document.querySelector('#ending-rank')?.textContent,
    time: document.querySelector('#ending-time')?.textContent,
    hints: document.querySelector('#ending-hints')?.textContent,
    gems: document.querySelector('#ending-gems')?.textContent,
    skills: document.querySelector('#ending-skills')?.textContent,
    pip: document.querySelector('.pip-level')?.textContent.trim(),
  }));
  log.push(['ending', ending]);

  return log;
}

